// Hand-built from InfluxDB's documented annotated-CSV format — TWO
// table blocks (different tag sets under the same measurement, exactly
// the case the live parser's header-re-detection has to handle), plus
// a numeric and a string field to confirm both value-formatting paths.
msg.payload = [
    '#datatype,string,long,dateTime:RFC3339,dateTime:RFC3339,dateTime:RFC3339,double,string,string,string',
    '#group,false,false,true,true,false,false,true,true,true',
    '#default,_result,,,,,,,,',
    ',result,table,_start,_stop,_time,_value,_field,_measurement,type',
    ',_result,0,2020-01-01T00:00:00Z,2026-08-20T00:00:00Z,2020-01-15T02:30:00Z,72,resting_hr,oura_sleep,long_sleep',
    ',_result,0,2020-01-01T00:00:00Z,2026-08-20T00:00:00Z,2020-01-16T02:30:00Z,68,resting_hr,oura_sleep,long_sleep',
    '',
    '#datatype,string,long,dateTime:RFC3339,dateTime:RFC3339,dateTime:RFC3339,string,string,string,string',
    '#group,false,false,true,true,false,false,true,true,true',
    '#default,_result,,,,,,,,',
    ',result,table,_start,_stop,_time,_value,_field,_measurement,type',
    ',_result,1,2020-01-01T00:00:00Z,2026-08-20T00:00:00Z,2020-01-15T02:30:00Z,deep,stage,oura_sleep,long_sleep'
].join('\n');
return msg;

// Deliberately a literal copy of n_wdr_parse_csv_to_lines' inner
// function (wherewhen_data_restore_flow.json) — if that logic ever
// changes, update BOTH copies, same convention already established for
// oura_sync_flow.json/oura_backfill_flow.json's shared line-building code.
function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }

function parseFluxCsvToLines(csvText) {
    const RESERVED = new Set(['result', 'table', '_start', '_stop', '_time', '_value', '_field', '_measurement']);
    const rawLines = csvText.split('\n').map(l => l.replace(/\r$/, ''));
    let header = null;
    const outLines = [];
    let dataRowCount = 0;

    rawLines.forEach(raw => {
        if (raw === '') { return; }
        if (raw.startsWith('#')) return;
        const cols = raw.split(',');
        if (cols.includes('_measurement') && (!header || !arraysEqual(cols, header))) {
            header = cols;
            return;
        }
        if (!header) return;
        if (cols.length !== header.length) return;

        const row = {};
        header.forEach((colName, i) => { row[colName] = cols[i]; });

        const measurement = row['_measurement'];
        const field = row['_field'];
        const value = row['_value'];
        const time = row['_time'];
        if (!measurement || !field || value === undefined || value === '' || !time) return;

        const tsMs = new Date(time).getTime();
        if (!Number.isFinite(tsMs)) return;

        const tagParts = [];
        header.forEach(colName => {
            if (!RESERVED.has(colName) && colName !== '' && row[colName] !== undefined && row[colName] !== '') {
                tagParts.push(esc(colName) + '=' + esc(row[colName]));
            }
        });

        const isNumeric = !isNaN(Number(value));
        const fieldPart = esc(field) + '=' + (isNumeric ? Number(value) : ('"' + String(value).replace(/"/g, '') + '"'));
        const tagStr = tagParts.length ? ',' + tagParts.join(',') : '';

        outLines.push(esc(measurement) + tagStr + ' ' + fieldPart + ' ' + (tsMs * 1000000));
        dataRowCount++;
    });

    return { lines: outLines, dataRowCount };
}
function arraysEqual(a, b) { return a.length === b.length && a.every((v, i) => v === b[i]); }

msg.parsed = parseFluxCsvToLines(msg.payload);
return msg;

const problems = [];
const lines = msg.parsed.lines;

if (msg.parsed.dataRowCount !== 3) {
    problems.push('Expected 3 data rows (2 numeric resting_hr + 1 string stage), got ' + msg.parsed.dataRowCount);
}
if (lines.length !== 3) {
    problems.push('Expected 3 output lines, got ' + lines.length);
}

// Line 1: numeric field, tag from first table block.
const l1 = lines[0] || '';
if (!/^oura_sleep,type=long_sleep resting_hr=72 \d+$/.test(l1)) {
    problems.push('Line 1 shape mismatch — expected "oura_sleep,type=long_sleep resting_hr=72 <ts>", got: ' + JSON.stringify(l1));
}

// Line 3: string field (quoted value), tag from SECOND table block — the
// real test of whether header re-detection across the blank-line/new-
// annotation-block boundary actually works.
const l3 = lines[2] || '';
if (!/^oura_sleep,type=long_sleep stage="deep" \d+$/.test(l3)) {
    problems.push('Line 3 (second table block) shape mismatch — expected \'oura_sleep,type=long_sleep stage="deep" <ts>\', got: ' + JSON.stringify(l3) + ' — if this is wrong but line 1 is right, the header re-detection across table blocks is the specific thing broken.');
}

// Timestamp sanity — Jan 15 2020 02:30 UTC should be in a plausible
// nanosecond range, not zero/NaN-derived.
const ts1 = (l1.match(/ (\d+)$/) || [])[1];
if (!ts1 || ts1.length < 15) {
    problems.push('Line 1 timestamp looks wrong (too short to be a real ns epoch): ' + ts1);
}

msg.payload = {
    result: problems.length ? 'PROBLEMS FOUND' : 'ALL CHECKS PASSED',
    problems: problems,
    parsed_lines: lines,
    data_row_count: msg.parsed.dataRowCount
};
return [msg, problems.length ? msg : null];

try {
    msg.payload = JSON.stringify(msg.payload, null, 2);
} catch (e) {
    msg.payload = 'JSON.stringify failed: ' + e.message;
}
return msg;
